<?php declare(strict_types=1);final class TaskStatus{public const PENDING='pending',READY='ready',RUNNING='running',WAITING_USER='waiting_user',WAITING_DEPENDENCY='waiting_dependency',COMPLETED='completed',FAILED='failed',CANCELLED='cancelled';public static function all():array{return[self::PENDING,self::READY,self::RUNNING,self::WAITING_USER,self::WAITING_DEPENDENCY,self::COMPLETED,self::FAILED,self::CANCELLED];}public static function assertValid(string$s):void{if(!in_array($s,self::all(),true))throw new InvalidArgumentException('status_invalid');}}
